  //           id      _   versao     _   produto     _   FEED|STORIES . ext
  const m = name.match(/^(\d+)[ _-]+([A-Za-z0-9]+)[ _-]+([A-Za-z0-9]+)[ _-]+(FEED|STOR(?:Y|IES))\.(?:png|jpg|jpeg|webp)$/i);
