(() => {
  const res = $('ADD - Enviar Imagem Stories').item.json;
  const images = res.body?.images || res.images || {};

  const fnameFromSet = $json.upload?.filename_stories;
  const pid  = String($json.pair_id || '');
  const ver  = String($json.pair_version || '').toUpperCase();
  const prod = String($json.product_token || '').toUpperCase();

  const expectedPng = `${pid}_${ver}_${prod}_STORIES.png`;
  const expectedJpg = `${pid}_${ver}_${prod}_STORIES.jpg`;

  const candidates = [fnameFromSet, expectedPng, expectedJpg].filter(Boolean);
  for (const name of candidates) if (images[name]?.hash) return images[name].hash;

  const firstKey = Object.keys(images)[0];
  return firstKey ? images[firstKey].hash : null;
})()
}}

