return items.map(item => {
  let waitSeconds = 0;

  try {
    const headers = item.json.headers || {};

    // Business Use Case
    const bucRaw = headers['x-business-use-case-usage'] || headers['X-Business-Use-Case-Usage'];
    if (bucRaw) {
      const usage = JSON.parse(bucRaw);
      const accId = Object.keys(usage)[0];
      const details = Array.isArray(usage[accId]) ? usage[accId][0] : usage[accId];
      const eta = Number(details?.estimated_time_to_regain_access || 0);
      if (eta > 0) waitSeconds = Math.max(waitSeconds, eta);
    }

    // Ad Account Usage
    const aauRaw = headers['x-ad-account-usage'] || headers['X-Ad-Account-Usage'];
    if (aauRaw) {
      const usage = JSON.parse(aauRaw);
      const accUsage = usage?.acc_id || usage;
      const eta = Number(accUsage?.estimated_time_to_regain_access || 0);
      const calls = Number(accUsage?.call_count || 0);

      if (eta > 0) waitSeconds = Math.max(waitSeconds, eta);
      if (waitSeconds === 0 && calls >= 90) waitSeconds = 60; // fallback de 1min
    }
  } catch (err) {
    // se nÃ£o conseguir ler, segue com 0
  }

  // Evitar rajada: sempre respeita ~400ms para POSTs
  const isPost = (item.json?.request?.method || '').toUpperCase() === 'POST';
  if (waitSeconds === 0 && isPost) {
    waitSeconds = 0.4;
  }

  return {
    json: {
      ...item.json,   // mantÃ©m todos os dados originais
      waitSeconds     // adiciona o tempo de espera
    }
  };
});

