/**
 * NORMALIZAÃ‡ÃƒO p/ payload: req.body.body.{ data, meta }
 * - Preserva objetivo original
 * - Corrige formatos (datas, orÃ§amentos, telefone)
 * - Normaliza pÃºblico (geo, idade, gÃªnero, interesses)
 * - Detecta Advantage+ placements
 * - Define modo (CREATE x ADD)
 */

function e164BR(raw) {
  if (!raw) return null;
  const d = String(raw).replace(/\D/g, "");
  return d.startsWith("55") ? d : "55" + d;
}

function toISODateIfYMD(s) {
  if (!s) return s;
  const str = String(s);
  if (/^\d{4}-\d{2}-\d{2}$/.test(str)) return `${str}T00:00:00-03:00`;
  return str;
}

function normalizeAdset(a = {}) {
  const o = { ...a };

  // ðŸ’° daily_budget_minor (centavos)
  if (o.daily_budget != null) {
    const n = Number(o.daily_budget);
    if (Number.isFinite(n)) {
      o.daily_budget_minor = n >= 100 ? Math.round(n) : Math.round(n * 100);
    }
  }

  // ðŸ“† datas simples -> ISO
  o.start_time = toISODateIfYMD(o.start_time);
  o.end_time = toISODateIfYMD(o.end_time);

  // ðŸ§­ TARGETING NORMALIZATION
  const tgt = o.targeting || {};

  // ðŸ—ºï¸ Geo padrÃ£o se nÃ£o vier nada
  if (!tgt.geo_locations) {
    tgt.geo_locations = { countries: ["BR"] };
  }

  // ðŸ‘¥ Idade padrÃ£o
  tgt.age_min = tgt.age_min || 18;
  tgt.age_max = tgt.age_max || 65;

  // âš§ GÃªneros vazios = todos
  if (Array.isArray(tgt.genders) && tgt.genders.length === 0) {
    delete tgt.genders;
  }

  // â¤ï¸ Interesses (vindo direto de adset.interests)
  if (Array.isArray(a.interests) && a.interests.length > 0) {
    tgt.flexible_spec = [{ interests: a.interests }];
  }

  // ðŸ“ Advantage+ placements: se nÃ£o especificar plataformas/posiÃ§Ãµes => auto
  const hasPositions =
    tgt.facebook_positions ||
    tgt.instagram_positions ||
    tgt.messenger_positions;
  const hasPlatforms =
    Array.isArray(tgt.publisher_platforms) &&
    tgt.publisher_platforms.length > 0;
  o.__auto_placements = !(hasPositions || hasPlatforms);

  // aplica targeting final
  o.targeting = tgt;

  return o;
}

function isUuid(v) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(v || ""));
}

function uuidv4() {
  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    const v = c === "x" ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

// 1ï¸âƒ£ Ler envelope do payload SEMPRE a partir do Entrada - Webhook Auto Ads
const webhookJson = $node["Entrada - Webhook Auto Ads"].json;
const envelope = webhookJson.body?.body ?? webhookJson.body ?? webhookJson;

const data = envelope.data || {};
const meta = envelope.meta || {};

// 2ï¸âƒ£ Objetivo
const objective = data.objective || data.campaign?.objective || "";
const campaignRef = data.campaign_ref || data.external_id || "";
const rawRunId =
  meta.run_id ||
  data.run_id ||
  meta.request_id ||
  "";
const runId = isUuid(rawRunId) ? String(rawRunId) : uuidv4();

// 3ï¸âƒ£ Montar saÃ­da normalizada
const out = {
  client: data.client || "",
  ad_account_id: String(data.ad_account_id || ""),

  // IDs
  campaign_id: String(data.campaign_id || ""),
  campaign_name: data.campaign?.name || data.campaign_name || "",
  campaign_ref: String(campaignRef),
  run_id: String(runId),

  objective,

  page_id: data.page_id || "",
  instagram_user_id: data.instagram_user_id || "",
  leadgen_form_id: data.leadgen_form_id || "",
  website_url: data.website_url || "",
  drive_folder_id: data.drive_folder_id || "",

  message_text: data.message_text || "Fale com a gente no WhatsApp ðŸ‘‡",
  title_text: data.title_text || "Ofertas",

  // ðŸ“£ Campanha
  campaign: data.campaign
    ? {
        ...data.campaign,
        objective,
        buying_type: data.campaign.buying_type || "AUCTION",
        status:
          data.campaign.status === "DRAFT"
            ? "PAUSED"
            : data.campaign.status || "PAUSED",
        special_ad_categories: data.campaign.special_ad_categories || ["NONE"],
      }
    : null,

  // ðŸ“Š AdSets normalizados
  adsets: Array.isArray(data.adsets)
    ? data.adsets.map(normalizeAdset)
    : [],

  // aÃ§Ã£o explÃ­cita
  action: data.action || null,

  // ðŸ§© Meta / callback
  meta: {
    request_id: meta.request_id || runId,
    run_id: String(runId),
    callback_url: meta.callback_url || null,
    sheet: envelope.sheet ?? null,
    rowIndex: envelope.rowIndex ?? null,
    campaign_ref: String(campaignRef),
  },

  // â˜Žï¸ WhatsApp (E.164)
  whatsapp_number: e164BR(data.whatsapp_number || data.whatsapp_number_id),
};

// 4ï¸âƒ£ Detectar modo (CREATE x ADD)
let mode = "ADD";
if (out.action === "create_campaign") mode = "CREATE";
if (out.action === "add_creatives") mode = "ADD";
if (!out.action) {
  if (!out.campaign_id && (out.campaign || (out.adsets && out.adsets.length)))
    mode = "CREATE";
}
out.mode = mode;
out.is_create = mode === "CREATE";

// Evita confusÃ£o com IDs curtos locais
if (out.is_create && out.campaign_id && out.campaign_id.length < 10) {
  out.meta.external_campaign_id = out.campaign_id;
  out.campaign_id = "";
}

return [{ json: out }];

const all = $json.body?.data ?? [];
const byCampaign = {};
const adsetById = {};
for (const s of all) {
  const cid = s.campaign_id || s.campaign?.id;
  if (!cid) continue;
  (byCampaign[cid] ||= []).push(s);
  adsetById[s.id] = s;
}
return [{ json: { byCampaign, adsetById, total_adsets: all.length } }];

// === UtilitÃ¡rios ===
const toBase = s => String(s||"")
  .toLowerCase()
  .replace(/\.(png|jpe?g|webp|gif|heic|heif|bmp|tif|tiff|svg)$/i,'');  // remove extensÃ£o

const norm = s => String(s||"")
  .normalize('NFD').replace(/\p{Diacritic}/gu,'')
  .toUpperCase().replace(/[^A-Z0-9]+/g,' ').trim();

// === Entrada: arquivos do Drive (Listar Arquivos) ===
const files = items.map(i => i.json); // {id, name, ...}

// Estrutura de pares por key
// key = {pair_id}__{product_token}
const pairs = Object.create(null);

/*
  PadrÃ£o novo:  id_versao_produto_posicionamento
    ex.: 01_TURBO_PULSE_FEED
         01_TURBO_PULSE_STORIES
  Regras:
  - pos = feed|story|stories (case-insensitive)
  - pair_id = 1o token se for DIGITOS (ex.: "01")
  - pair_version = 2o token (ex.: "TURBO")
  - product_name = o restante antes do pos (ex.: "PULSE")
  - product_token = Ãºltima palavra de product_name normalizado (ex.: "PULSE")
  - key = {pair_id||"00"}__{product_token}
*/
function parseFileName(nameRaw) {
  const base = toBase(nameRaw);
  const parts = base.split(/[_\-\s]+/).filter(Boolean);
  if (!parts.length) return null;

  const pos = parts[parts.length - 1];
  if (!/^(feed|story|stories)$/i.test(pos)) return null;

  // tira posicionamento
  parts.pop();

  let pair_id = null, pair_version = null, product_name = null;

  // id numÃ©rico?
  if (parts.length && /^\d+$/.test(parts[0])) {
    pair_id = parts.shift();
  }

  // versÃ£o (opcional) â€” se restarem 2+ tokens, consideramos o 2Âº como versÃ£o
  if (parts.length >= 2) {
    pair_version = parts.shift();   // TURBO
  }

  // o que sobrou Ã© o produto (nome livre)
  product_name = parts.join(' ').trim();
  if (!product_name) {
    // retrocompatibilidade: sem id/versÃ£o, considera tudo produto
    product_name = (pair_id ? pair_id + ' ' : '') + (pair_version ? pair_version + ' ' : '');
    product_name = (product_name + '').trim() || base; // fallback
  }

  // token = Ãºltima palavra do produto normalizado
  const words = norm(product_name).split(/\s+/).filter(Boolean);
  const product_token = words.length ? words[words.length - 1] : null;

  const positioning = pos.toLowerCase() === 'story' ? 'stories' : pos.toLowerCase();

  return {
    pair_id: pair_id || "00",
    pair_version: pair_version || null,
    product_name,
    product_token,
    positioning,
  };
}

// Monta estrutura de pares completos
for (const f of files) {
  const parsed = parseFileName(f.name);
  if (!parsed || !parsed.product_token) continue;
  const { pair_id, product_token, pair_version, product_name, positioning } = parsed;

  const key = `${pair_id}__${product_token}`;
  if (!pairs[key]) {
    pairs[key] = {
      key,
      // metadados do par
      pair_id,                    // "01"
      pair_version,               // "TURBO"
      pair_product_name: product_name, // "PULSE"
      product_token,              // "PULSE"
      // compat + campos esperados a jusante
      feed: null,
      stories: null,
      feed_file_id: null,
      story_file_id: null,
    };
  }

  if (positioning === 'feed') {
    pairs[key].feed = f.id;
    pairs[key].feed_file_id = f.id;
  } else if (positioning === 'stories') {
    pairs[key].stories = f.id;
    pairs[key].story_file_id = f.id;
  }
}

// Emite apenas pares COMPLETOS (feed + stories)
const out = [];
for (const k of Object.keys(pairs)) {
  const p = pairs[k];
  if (p.feed && p.stories) {
    out.push({ json: p });
  }
}

if (!out.length) {
  throw new Error("Nenhum par completo (feed+stories) encontrado. Nomeie assim: 01_VERSAO_PRODUTO_FEED e 01_VERSAO_PRODUTO_STORIES");
}

return out;

// ===== ajuste nomes conforme seu workflow =====
const BASE_NODE   = "Entrada - Normalizar Payload";
const MAP_NODE    = "ADD - Mapear Adsets por Campanha";
const ADSETS_NODE = "ADD - Listar Adsets Ativos";          // HTTP Full Response
const CAMPAIGN_NODE = "ADD - Listar Campanhas Ativas";
const PAIRS_NODE  = "ADD - Unir Hashes aos Pares";

// ===== helpers =====
const norm = s => String(s||"")
  .normalize('NFD').replace(/\p{Diacritic}/gu,'')
  .toUpperCase().replace(/[^A-Z0-9]+/g,' ').trim();

const tokenFromPairKey = key => {
  const parts = String(key||"").split("__");
  return parts.length >= 2 ? norm(parts[1]) : null;
};

const MAX_ADSETS_PER_CAMPAIGN = 20;
const FILTER_EFFECTIVE = new Set(['ACTIVE','PAUSED']);

// ===== base/contexto =====
const base = ($items(BASE_NODE)[0]?.json) || {};

// ===== 1) MAPA DE ADSETS: tenta "Montar Mapa...", senÃ£o reidrata do HTTP =====
function buildByCampaignFromMapNode() {
  const item = $items(MAP_NODE)[0];
  const raw = item?.json?.byCampaign || {};
  const out = {};
  for (const k of Object.keys(raw)) {
    out[String(k)] = (raw[k]||[]).map(a => ({ id: String(a.id), name: a.name||"" }));
  }
  return out;
}

function buildByCampaignFromHttp() {
  const n = $node[ADSETS_NODE]?.json || {};
  let data = [];
  if (Array.isArray(n.allAdsets)) data = n.allAdsets;
  else if (Array.isArray(n.data)) data = n.data;
  else if (Array.isArray(n.body?.data)) data = n.body.data;

  const out = {};
  for (const a of data || []) {
    const cid = a?.campaign_id || a?.campaign?.id;
    const eff = a?.effective_status || a?.status;
    const cfg = a?.configured_status;
    if (!cid) continue;
    if (FILTER_EFFECTIVE.size && eff && !FILTER_EFFECTIVE.has(eff)) continue;
    if (cfg === 'ARCHIVED') continue;
    const key = String(cid);
    (out[key] ??= []).push({ id: String(a.id), name: a.name || "" });
  }
  return out;
}

let byCampaign = buildByCampaignFromMapNode();
if (!Object.keys(byCampaign).length) {
  byCampaign = buildByCampaignFromHttp();
}

// ===== 2) CAMPANHAS: aceita vÃ¡rios formatos =====
let campaigns = [];
const cj = $node[CAMPAIGN_NODE]?.json;
if (Array.isArray(cj?.campaigns)) campaigns = cj.campaigns;
else if (Array.isArray(cj?.data)) campaigns = cj.data;
else if (Array.isArray(cj?.body?.data)) campaigns = cj.body.data;
else campaigns = $items(CAMPAIGN_NODE).map(i => i.json);

// ===== 3) PARES (p/ derivar token) =====
const pairs = $items(PAIRS_NODE).map(i => i.json);
const pairTokens = new Set(
  pairs.map(p => tokenFromPairKey(p.key)).filter(Boolean)
);

// ===== 4) DerivaÃ§Ã£o de token de produto =====
function deriveTokenForCampaign(c) {
  // prioridade: jÃ¡ veio pronto?
  if (c.product_token) return norm(c.product_token);

  // tenta casar com tokens dos pares no nome da campanha:
  const name = norm(c.name || c.campaign_name || "");
  for (const tk of pairTokens) {
    // token inteiro como palavra
    const re = new RegExp(`(^|\\s)${tk}(\\s|$)`);
    if (re.test(name)) return tk;
  }

  // fallback bem simples: Ãºltima palavra do nome
  const parts = name.split(/\s+/).filter(Boolean);
  return parts.length ? parts[parts.length - 1] : "";
}

// ===== 5) Expandir campanhas + anexar adsets =====
const out = [];
const skipped = [];

for (const c of campaigns) {
  const cid = String(c.id ?? c.campaign_id ?? c.campaign?.id ?? "");
  if (!cid) { skipped.push({ reason: "NO_CAMPAIGN_ID" }); continue; }

  const eff = c.effective_status ?? c.status;
  if (FILTER_EFFECTIVE.size && eff && !FILTER_EFFECTIVE.has(eff)) {
    skipped.push({ campaign_id: cid, reason: `FILTERED_STATUS:${eff}` });
    continue;
  }

  const cname = c.name ?? c.campaign_name ?? "";
  const objective = c.objective ?? c.objective_type ?? "";
  const product_token = deriveTokenForCampaign(c); // <<< agora sempre tenta preencher

  const list = byCampaign[cid] || [];
  const adset_ids = [...new Set(list.map(a => a.id))].slice(0, MAX_ADSETS_PER_CAMPAIGN);

  out.push({
    json: {
      campaign_id: cid,
      campaign_name: cname,
      objective,
      product_token,                     // <<< preencheu
      campaign_adsets: list,             // <<< preencheu (se existir no mapa)
      adset_ids,                         // <<< preencheu
      _adsets_count_for_campaign: list.length,

      // contexto Ãºtil
      ad_account_id: base.ad_account_id,
      page_id: base.page_id,
      instagram_user_id: base.instagram_user_id,
      leadgen_form_id: base.leadgen_form_id,
      drive_folder_id: base.drive_folder_id,
      message_text: base.message_text,
      title_text: base.title_text
    }
  });
}

// nunca quebra: devolve pelo menos um log
if (!out.length) return [{ json: { _skipped: skipped, msg: "Nenhuma campanha elegÃ­vel / sem match no mapa" } }];
if (skipped.length) out[0].json._skipped = skipped;

return out;

// ===== nomes dos nÃ³s fontes =====
const BASE_NODE   = "Entrada - Normalizar Payload";
const CAM_NODE    = "ADD - Expandir Campanhas e Produto"; // troque para "...1" se for o seu caso
const PAIRS_NODE  = "ADD - Unir Hashes aos Pares";

// ===== coletas =====
const baseItems = $items(BASE_NODE);
const camItems  = $items(CAM_NODE);
const pairItems = $items(PAIRS_NODE);

if (!baseItems?.length) throw new Error(`NÃ£o achei "${BASE_NODE}".`);
if (!camItems?.length)  throw new Error(`NÃ£o achei "${CAM_NODE}".`);
if (!pairItems?.length) throw new Error(`NÃ£o achei "${PAIRS_NODE}".`);

const base = baseItems[0].json;
const campaigns = camItems.map(i => i.json);
const pairs = pairItems.map(i => i.json);

// ===== utils =====
const norm = s => String(s||"")
  .normalize('NFD').replace(/\p{Diacritic}/gu,'')
  .toUpperCase().replace(/[^A-Z0-9]+/g,' ').trim();

function toE164(raw, countryHint = "BR") {
  if (!raw) return null;
  const digits = String(raw).replace(/\D/g, "");
  if (!digits) return null;
  if (countryHint === "BR" && !digits.startsWith("55")) return "55" + digits;
  return digits;
}

// preferir o token vindo do item; se faltar, extrair do pair_key (depois do "__")
function tokenFromPair(p) {
  const direct = norm(p.product_token);
  if (direct) return direct;
  const key = String(p.key || "");
  const parts = key.split("__");
  const candidate = parts.length > 1 ? parts[1] : parts[0];
  return norm(candidate);
}

// ===== conjunto de tokens presentes na pasta (pares vÃ¡lidos) =====
const tokensWanted = new Set(
  pairs.map(p => tokenFromPair(p)).filter(Boolean)
);

// ===== filtra campanhas cujo product_token existe na pasta =====
const filteredCampaigns = campaigns.filter(c =>
  tokensWanted.has(norm(c.product_token))
);

// ===== emite correspondÃªncias par â†” campanha por token exato =====
const wppE164 = toE164(base.whatsapp_number, "BR");
const wppLink = wppE164 ? `https://wa.me/${wppE164}` : null;
const message_text = base.message_text || "Fale com a gente no WhatsApp ðŸ‘‡";
const title_text   = base.title_text   || "Ofertas";

const out = [];

for (const c of filteredCampaigns) {
  const ctoken = norm(c.product_token);

  // pares cujo token == token da campanha
  const mine = pairs.filter(p => tokenFromPair(p) === ctoken);

  const campaign_adsets = Array.isArray(c.campaign_adsets) ? c.campaign_adsets : [];
  const adset_ids = Array.from(new Set(
    Array.isArray(c.adset_ids) ? c.adset_ids : []
  ));
  if (!adset_ids.length) continue;

  for (const p of mine) {
    out.push({
      json: {
        // campanha
        campaign_id: c.campaign_id,
        campaign_name: c.campaign_name,
        objective: c.objective,
        product_token: ctoken,

        // par (hashes + chave)
        pair_key: p.key,
        feed_image_hash: p.feed_image_hash,
        story_image_hash: p.story_image_hash,

        // (opcionalmente, repasse tambÃ©m para naming/log)
        pair_id: p.pair_id ?? null,
        pair_version: p.pair_version ?? null,

        // adsets
        campaign_adsets,
        adset_ids,

        // contexto/IDs
        ad_account_id: base.ad_account_id,
        page_id: base.page_id,
        instagram_user_id: base.instagram_user_id,
        leadgen_form_id: base.leadgen_form_id,

        // whatsapp
        whatsapp_number: wppE164,
        whatsapp_click_link: wppLink,

        // textos
        message_text,
        title_text,
      }
    });
  }
}

if (!out.length) {
  throw new Error("Sem correspondÃªncia: sÃ³ passam campanhas com produtos existentes na pasta.");
}

return out;

// === UtilitÃ¡rios ===
const toBase = s => String(s||"")
  .toLowerCase()
  .replace(/\.(png|jpe?g|webp|gif|heic|heif|bmp|tif|tiff|svg)$/i,'');  // remove extensÃ£o

const norm = s => String(s||"")
  .normalize('NFD').replace(/\p{Diacritic}/gu,'')
  .toUpperCase().replace(/[^A-Z0-9]+/g,' ').trim();

// === Entrada: arquivos do Drive (Listar Arquivos) ===
const files = items.map(i => i.json); // {id, name, ...}

// Estrutura de pares por key
// key = {pair_id}__{product_token}
const pairs = Object.create(null);

/*
  PadrÃ£o novo:  id_versao_produto_posicionamento
    ex.: 01_TURBO_PULSE_FEED
         01_TURBO_PULSE_STORIES
  Regras:
  - pos = feed|story|stories (case-insensitive)
  - pair_id = 1o token se for DIGITOS (ex.: "01")
  - pair_version = 2o token (ex.: "TURBO")
  - product_name = o restante antes do pos (ex.: "PULSE")
  - product_token = Ãºltima palavra de product_name normalizado (ex.: "PULSE")
  - key = {pair_id||"00"}__{product_token}
*/
function parseFileName(nameRaw) {
  const base = toBase(nameRaw);
  const parts = base.split(/[_\-\s]+/).filter(Boolean);
  if (!parts.length) return null;

  const pos = parts[parts.length - 1];
  if (!/^(feed|story|stories)$/i.test(pos)) return null;

  // tira posicionamento
  parts.pop();

  let pair_id = null, pair_version = null, product_name = null;

  // id numÃ©rico?
  if (parts.length && /^\d+$/.test(parts[0])) {
    pair_id = parts.shift();
  }

  // versÃ£o (opcional) â€” se restarem 2+ tokens, consideramos o 2Âº como versÃ£o
  if (parts.length >= 2) {
    pair_version = parts.shift();   // TURBO
  }

  // o que sobrou Ã© o produto (nome livre)
  product_name = parts.join(' ').trim();
  if (!product_name) {
    // retrocompatibilidade: sem id/versÃ£o, considera tudo produto
    product_name = (pair_id ? pair_id + ' ' : '') + (pair_version ? pair_version + ' ' : '');
    product_name = (product_name + '').trim() || base; // fallback
  }

  // token = Ãºltima palavra do produto normalizado
  const words = norm(product_name).split(/\s+/).filter(Boolean);
  const product_token = words.length ? words[words.length - 1] : null;

  const positioning = pos.toLowerCase() === 'story' ? 'stories' : pos.toLowerCase();

  return {
    pair_id: pair_id || "00",
    pair_version: pair_version || null,
    product_name,
    product_token,
    positioning,
  };
}

// Monta estrutura de pares completos
for (const f of files) {
  const parsed = parseFileName(f.name);
  if (!parsed || !parsed.product_token) continue;
  const { pair_id, product_token, pair_version, product_name, positioning } = parsed;

  const key = `${pair_id}__${product_token}`;
  if (!pairs[key]) {
    pairs[key] = {
      key,
      // metadados do par
      pair_id,                    // "01"
      pair_version,               // "TURBO"
      pair_product_name: product_name, // "PULSE"
      product_token,              // "PULSE"
      // compat + campos esperados a jusante
      feed: null,
      stories: null,
      feed_file_id: null,
      story_file_id: null,
    };
  }

  if (positioning === 'feed') {
    pairs[key].feed = f.id;
    pairs[key].feed_file_id = f.id;
  } else if (positioning === 'stories') {
    pairs[key].stories = f.id;
    pairs[key].story_file_id = f.id;
  }
}

// Emite apenas pares COMPLETOS (feed + stories)
const out = [];
for (const k of Object.keys(pairs)) {
  const p = pairs[k];
  if (p.feed && p.stories) {
    out.push({ json: p });
  }
}

if (!out.length) {
  throw new Error("Nenhum par completo (feed+stories) encontrado. Nomeie assim: 01_VERSAO_PRODUTO_FEED e 01_VERSAO_PRODUTO_STORIES");
}

return out;

