  if (v == null) return [];
  if (Array.isArray(v)) return v.map(String);
  if (typeof v === 'number') return [String(v)];
  if (typeof v === 'string') {
    try { const j = JSON.parse(v); if (Array.isArray(j)) return j.map(String); } catch (_){}
    return v.split(/[\s,;|]+/).map(t => t.trim()).filter(Boolean);
  }
  if (typeof v === 'object' && v.id) return [String(v.id)];
  return [];
};
const uniq = (a) => [...new Set(a.map(String).filter(Boolean))];
const getFromNodeIdx = (node, idx) => {
  try { return ($items(node)[idx] || {}).json || {}; } catch { return {}; }
};
const getFromNode0 = (node) => {
  try { return ($items(node)[0] || {}).json || {}; } catch { return {}; }
};

// ---------------- processamento ----------------
const out = [];
const bad = [];

for (let idx = 0; idx < $items().length; idx++) {
  const j0 = $items()[idx].json || {};

  // --- 1) HEADERS (API usage) ---
  let headers = j0.headers;
  if (!headers) {
    const httpIt = ($items(HTTP_NODE_NAME)[idx] || $items(HTTP_NODE_NAME)[0] || {}).json;
    headers = httpIt?.headers;
  }
  headers = headers || {};

  // x-business-use-case-usage â†’ {"<act_id>":[{type:"ads_management",call_count,...}]}
  let callCount=0, totalTime=0, cpuTime=0, regain=0, tier='unknown';
  const bizRaw = headers['x-business-use-case-usage'];
  if (bizRaw) {
    const obj = parseJson(bizRaw) || {};
    const k = Object.keys(obj)[0];
    const arr = Array.isArray(obj[k]) ? obj[k] : [];
    for (const m of arr) {
      callCount = Math.max(callCount, Number(m.call_count || 0));
      totalTime = Math.max(totalTime, Number(m.total_time || 0));
      cpuTime   = Math.max(cpuTime,   Number(m.total_cputime || 0));
      regain    = Math.max(regain,    Number(m.estimated_time_to_regain_access || 0));
      tier      = m.ads_api_access_tier || tier;
    }
  }

  // HeurÃ­stica de respiro (ajuste conforme sua operaÃ§Ã£o)
  let level='ok', waitSeconds = Number(j0.waitSeconds ?? DEFAULT_WAIT_SECONDS);
  if (regain > 0)                               { level='blocked'; waitSeconds = Math.max(waitSeconds, 60); }
  else if (totalTime >= 90 || callCount >= 90)  { level='danger';  waitSeconds = Math.max(waitSeconds, 30); }
  else if (totalTime >= 70 || callCount >= 60)  { level='caution'; waitSeconds = Math.max(waitSeconds, 10); }

  // --- 2) creative_id (promove de vÃ¡rios formatos) ---
  const httpResp = ($items(HTTP_NODE_NAME)[idx] || {}).json || {};
  const creative_id = String(
    j0.creative_id ?? j0.body?.id ?? j0.id ?? httpResp.body?.id ?? httpResp.id ?? ''
  );

